package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	readInt := func() int {
		scanner.Scan()
		val, _ := strconv.Atoi(scanner.Text())
		return val
	}

	l := readInt()
	r := readInt()

	n := 9
	ten := make([]int, n+1)
	ten[0] = 1
	for i := 1; i <= n; i++ {
		ten[i] = 10 * ten[i-1]
	}

	var answer int64
	luckyNumbers := make([]int64, 0)

	for length := 1; length <= n; length++ {
		for cur := 0; cur < (1 << length); cur++ {
			value := 0
			for j := 0; j < length; j++ {
				if (cur & (1 << j)) == (1 << j) {
					value += ten[j] * 7
				} else {
					value += ten[j] * 4
				}
			}
			luckyNumbers = append(luckyNumbers, int64(value))
		}
	}

	luckyNumbers = append(luckyNumbers, 4444444444)

	lastNumber := int64(l)

	for _, luckyNumber := range luckyNumbers {
		if luckyNumber > int64(r) {
			answer += int64(r - int(lastNumber) + 1) * luckyNumber
			break
		}
		if luckyNumber >= int64(l) {
			answer += int64(luckyNumber - lastNumber + 1) * luckyNumber
			lastNumber = luckyNumber + 1
		}
	}

	fmt.Println(answer)
}

