package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewScanner(os.Stdin)
	in.Split(bufio.ScanWords)

	var l, r int64
	in.Scan()
	fmt.Sscanf(in.Text(), "%d", &l)
	in.Scan()
	fmt.Sscanf(in.Text(), "%d", &r)

	var luckyNumbers []int64

	// Generate lucky numbers up to 10 digits (1 to 9 digits + sentinel)
	// Using recursion/backtracking to generate in sorted order naturally, or generate all and sort.
	// Java generates by length then bitmask, which produces sorted order.
	// Let's replicate the bitmask logic for exactness, or just generate and sort.
	// Max 2^10 = 1024 numbers, sorting is trivial.

	var generate func(current int64, length int)
	generate = func(current int64, length int) {
		if length > 10 {
			return
		}
		if length > 0 {
			luckyNumbers = append(luckyNumbers, current)
		}
		generate(current*10+4, length+1)
		generate(current*10+7, length+1)
	}

	generate(0, 0)
	sort.Slice(luckyNumbers, func(i, j int) bool { return luckyNumbers[i] < luckyNumbers[j] })

	// Add sentinel
	luckyNumbers = append(luckyNumbers, 4444444444)

	var answer int64
	lastNumber := l

	for _, luckyNumber := range luckyNumbers {
		if luckyNumber > r {
			answer += (r - lastNumber + 1) * luckyNumber
			break
		}
		if luckyNumber >= l {
			answer += (luckyNumber - lastNumber + 1) * luckyNumber
			lastNumber = luckyNumber + 1
		}
	}

	fmt.Println(answer)
}

